import type { DocumentNode, FragmentDefinitionNode, SelectionSetNode } from "graphql";

export function enforceGraphQLLimits(doc: DocumentNode, maxDepth = 7, maxAliases = 15): void {
  const fragments = new Map<string, FragmentDefinitionNode>();
  for (const def of doc.definitions) {
    if (def.kind === "FragmentDefinition") fragments.set(def.name.value, def);
  }
  let aliasCount = 0;
  function walk(set: SelectionSetNode | undefined, depth: number, seenFrags: Set<string>): void {
    if (!set) return;
    if (depth > maxDepth) throw new Error(`GraphQL depth exceeds ${maxDepth}`);
    for (const sel of set.selections) {
      if (sel.kind === "Field") {
        if (sel.alias && ++aliasCount > maxAliases) {
          throw new Error(`GraphQL alias count exceeds ${maxAliases}`);
        }
        walk(sel.selectionSet, depth + 1, seenFrags);
      } else if (sel.kind === "InlineFragment") {
        walk(sel.selectionSet, depth, seenFrags);
      } else if (sel.kind === "FragmentSpread") {
        const name = sel.name.value;
        if (seenFrags.has(name)) throw new Error("cyclic GraphQL fragment detected");
        const frag = fragments.get(name);
        if (!frag) throw new Error(`unknown GraphQL fragment: ${name}`);
        const nextSeen = new Set(seenFrags);
        nextSeen.add(name);
        walk(frag.selectionSet, depth, nextSeen);
      }
    }
