```python
import ast

SUBPROC_FUNCS = {"run", "Popen", "call", "check_call", "check_output"}

def _dotted_name(node: ast.AST) -> str:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        prefix = _dotted_name(node.value)
        return f"{prefix}.{node.attr}" if prefix else node.attr
    return ""

class SinkVisitor(ast.NodeVisitor):
    def __init__(self) -> None:
        self.findings: list[tuple[int, str]] = []

    def visit_Call(self, node: ast.Call) -> None:
        name = _dotted_name(node.func)
        kw = {k.arg: k.value for k in node.keywords if k.arg}
        if name in {"eval", "exec", "builtins.eval", "builtins.exec"}:
            self.findings.append((node.lineno, "PY001_DYNAMIC_EXEC"))
        elif name in {"pickle.loads", "pickle.load", "marshal.loads"}:
            self.findings.append((node.lineno, "PY002_UNSAFE_DESERIALIZE"))
        elif name == "yaml.load":
            loader = _dotted_name(kw.get("Loader", ast.AST()))
            if loader not in {"SafeLoader", "yaml.SafeLoader", "CSafeLoader", "yaml.CSafeLoader"}:
                self.findings.append((node.lineno, "PY003_UNSAFE_YAML_LOAD"))
        elif name.startswith("subprocess.") and name.split(".", 1)[1] in SUBPROC_FUNCS:
            shell_arg = kw.get("shell")
            if isinstance(shell_arg, ast.Constant) and shell_arg.value is True:
                self.findings.append((node.lineno, "PY004_SUBPROCESS_SHELL_TRUE"))
        self.generic_visit(node)

def scan_python_sinks(source: str) -> list[tuple[int, str]]:
    visitor = SinkVisitor()
    visitor.visit(ast.parse(source))
    return sorted(visitor.findings)
