from collections.abc import Iterable
import re

def pep503_norm(name: str) -> str:
    base = re.split(r"[<>=!~;\[@\s]", name.strip(), maxsplit=1)[0]
    return re.sub(r"[-_.+]+", "-", base).lower()

def levenshtein(a: str, b: str) -> int:
    if abs(len(a) - len(b)) > 2:
        return 99
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        cur = [i]
        for j, cb in enumerate(b, start=1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

def find_typosquat_packages(
    installed_reqs: Iterable[str],
    trusted_baseline: set[str],
) -> list[tuple[str, str, int]]:
    norm_trusted = {pep503_norm(pkg) for pkg in trusted_baseline if pkg}
    suspects: list[tuple[str, str, int]] = []
    for raw in installed_reqs:
        cand = pep503_norm(raw)
        if not cand or cand in norm_trusted or len(cand) < 4:
            continue
        for good in sorted(norm_trusted):
            dist = levenshtein(cand, good)
            if dist == 1:
                suspects.append((cand, good, dist))
    return suspects
```
