import hashlib
import hmac

def leaf_hash(data: bytes) -> bytes:
    return hashlib.sha256(b"\x00" + data).digest()

def node_hash(left: bytes, right: bytes) -> bytes:
    return hashlib.sha256(b"\x01" + left + right).digest()

def verify_merkle_inclusion(
    leaf_data: bytes,
    proof: list[tuple[str, bytes]],
    expected_root: bytes,
) -> bool:
    if len(expected_root) != 32 or len(proof) > 64:
        return False
    cur = leaf_hash(leaf_data)
    for side, sibling in proof:
        if len(sibling) != 32 or side not in ("L", "R"):
            return False
        cur = node_hash(sibling, cur) if side == "L" else node_hash(cur, sibling)
    return hmac.compare_digest(cur, expected_root)
