WEAK_SIG_ALGS = {"md5WithRSAEncryption", "sha1WithRSAEncryption", "ecdsa-with-SHA1"}
MAX_LEAF_LIFETIME_S = 398 * 86400

def _match_san_dns(pattern: str, host: str) -> bool:
    pat = pattern.rstrip(".").lower()
    target = host.rstrip(".").lower()
    if "*" not in pat:
        return pat == target
    if not pat.startswith("*.") or "*" in pat[2:] or pat.count(".") < 2:
        return False
    host_labels = target.split(".")
    pat_labels = pat.split(".")
    return len(host_labels) == len(pat_labels) and host_labels[1:] == pat_labels[1:]

def validate_cert_policy(cert_meta: dict[str, Any], hostname: str, now_unix: int) -> list[str]:
    errors: list[str] = []
    nb, na = int(cert_meta["not_before"]), int(cert_meta["not_after"])
    if now_unix < nb or now_unix > na:
        errors.append("certificate expired or not yet valid")
    if (na - nb) > MAX_LEAF_LIFETIME_S:
        errors.append("leaf validity exceeds 398-day baseline")
    if str(cert_meta.get("sig_alg", "")) in WEAK_SIG_ALGS:
        errors.append("weak signature hash algorithm (MD5/SHA-1)")
    sans = [str(s) for s in (cert_meta.get("dns_sans") or [])]
    if not any(_match_san_dns(san, hostname) for san in sans):
        errors.append(f"hostname {hostname!r} not covered by DNS SANs")
