```go
package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"
)

func VerifyHandler(secret []byte, next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tsStr := r.Header.Get("X-Webhook-Timestamp")
		ts, err := strconv.ParseInt(tsStr, 10, 64)
		if err != nil || abs64(time.Now().Unix()-ts) > 300 {
			http.Error(w, "stale or invalid timestamp", http.StatusUnauthorized)
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
		body, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
			return
		}
		sigHex := strings.TrimPrefix(r.Header.Get("X-Hub-Signature-256"), "sha256=")
		gotSig, err := hex.DecodeString(sigHex)
		if err != nil {
			http.Error(w, "malformed signature", http.StatusUnauthorized)
			return
		}
		mac := hmac.New(sha256.New, secret)
		mac.Write([]byte(tsStr + "."))
		mac.Write(body)
		if !hmac.Equal(gotSig, mac.Sum(nil)) {
			http.Error(w, "bad signature", http.StatusUnauthorized)
			return
		}
		next(w, r)
	}
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}
