func VerifyManifest(pub ed25519.PublicKey, rawJSON, sig []byte) (*Manifest, error) {
	if len(pub) != ed25519.PublicKeySize || len(sig) != ed25519.SignatureSize {
		return nil, errors.New("invalid key or signature length")
